def describe_error(error: dict[str, Any]) -> dict[str, Any]:
    """Summarise a single pyairahome ``Error`` dict for display.

    The ``Error`` protobuf serialises (via ``MessageToDict`` with proto field
    names preserved and enums as names) to a dict with ``severity``,
    ``occurred_at`` and exactly one of ``ccv``/``aira``/``power`` holding the
    error-code enum value *name*. Returns a flat dict of display fields;
    ``description``/``consequence``/``suggested_action`` are ``None`` when the
    code has no known text.
    """
    code: Any = None
    category: str | None = None
    for field in _CATEGORY_FIELDS:
        value = error.get(field)
        if value:
            code = value
            category = field
            break

    info = ERROR_CODES.get(code, {}) if isinstance(code, str) else {}
    return {
        "code": code if code is not None else "UNKNOWN",
        "category": category,
        "severity": error.get("severity"),
        "occurred_at": error.get("occurred_at"),
        "description": info.get("description"),
        "consequence": info.get("consequence"),
        "suggested_action": info.get("suggested_action"),
    }
